<?php require 'config/auth.php';require_login();require 'config/database.php';$msg='';$user_id=$_SESSION['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');if($name!==''&&filter_var($email,FILTER_VALIDATE_EMAIL)){$stmt=$conn->prepare("UPDATE users SET name=?,email=? WHERE id=?");$stmt->bind_param("ssi",$name,$email,$user_id);if($stmt->execute()){$_SESSION['name']=$name;$_SESSION['email']=$email;$msg='Profile updated.';}}}$stmt=$conn->prepare("SELECT name,email,role,created_at FROM users WHERE id=?");$stmt->bind_param("i",$user_id);$stmt->execute();$user=$stmt->get_result()->fetch_assoc();$pageTitle='Profile';include 'header.php';?><h2>Profile</h2><?php if($msg):?><div class="alert"><?=htmlspecialchars($msg)?></div><?php endif;?><form method="post"><label>Name</label><input type="text" name="name" value="<?=htmlspecialchars($user['name'])?>" required><label>Email</label><input type="email" name="email" value="<?=htmlspecialchars($user['email'])?>" required><p><strong>Role:</strong> <?=htmlspecialchars($user['role'])?></p><button class="btn" type="submit">Update Profile</button></form><?php include 'footer.php'; ?>